 Z=np.hstack([B[j]^B[61]for j in J if j!=61]);R=f.mm(T[O],B[61]);f.need(f.rank(R)==4 and all(np.array_equal(f.mm(T[O],B[j]),R)for j in J),'actual95 common injective forced-K readout');V=sorted(set(sum([readouts[str(j)]['95']['D_inputs']for j in J],[])));f.need(f.rank(Z)==24 and f.rank(np.hstack([Z,B[61]]))==28,'literal native contrast and augmented ranks');f.need(f.rank(T[np.ix_(O,V)])==8 and not np.any(f.mm(T[O],Z)),'actual eight-row annihilator')
 rr={r:readouts['0'][str(r)]['D_outputs']for r in[48,73]};d=16-f.rank(np.vstack([T[np.ix_(rr[r],V)]for r in[48,73]]));f.need(d==2,'ordinary-overlap physical gate');result={'status':'PASS_INDEPENDENT_ACTUAL95_PENCIL_FORCED_K_READOUT','contrast_rank':24,'augmented_rank':28,'actual95_common_response_rank':4,'actual95_native_row_rank':8,'actual95_contrast_response_rank':0,'retained48_73_overlap_dimension':d,'common_response':R.tolist(),'off_D_isolation':leaks,'complete_fifth_receiver':False,'new_complete_kappa':False};out.mkdir(parents=True,exist_ok=True);f.save(out/'ACTUAL95-REVIEW.json',result);pins={str(p.relative_to(repo))if p.is_relative_to(repo)else str(p):hashlib.sha256(p.read_bytes()).hexdigest()for p in files};f.save(out/'ACTUAL95-SOURCE-PINS.json',pins);print(result['status'],leaks,flush=True)
